import java.time.Duration;
import java.util.*;
import java.util.function.*;

import io.github.resilience4j.retry.*;

public class Main {
    public static void main(String[] args) {
        GudangPalsu gudang = new GudangPalsu("timeout", "timeout", "ok");
        Retry retry = Retry.of("gudang", RetryConfig.custom().maxAttempts(2).waitDuration(Duration.ofMillis(10)).build());
        try {
            System.out.println(Retry.decorateSupplier(retry, () -> gudang.cekStok("kopi")).get());
        } catch (IllegalStateException e) {
            System.out.println("Gagal: " + e.getMessage());
        }
        System.out.println("Panggilan: " + gudang.panggilan);
    }
}

class GudangPalsu {
    private final Deque<String> jadwal;
    int panggilan;

    GudangPalsu(String... jadwal) {
        this.jadwal = new ArrayDeque<>(Arrays.asList(jadwal));
    }

    int cekStok(String barang) {
        panggilan++;
        String hasil = jadwal.isEmpty() ? "ok" : jadwal.poll();
        if (hasil.equals("timeout")) {
            throw new IllegalStateException("timeout ke gudang");
        }
        if (hasil.equals("400")) {
            throw new IllegalArgumentException("barang tidak dikenal: " + barang);
        }
        return 7;
    }
}

