import java.time.Duration;
import java.util.*;
import java.util.function.*;

import io.github.resilience4j.retry.*;

public class Main {
    public static void main(String[] args) {
        Scanner in = new Scanner(System.in);
        KurirPalsu kurir = new KurirPalsu(in.nextLine());
        try {
            System.out.println(kurir.lacak("JKT123"));
        } catch (IllegalStateException e) {
            System.out.println("Gagal: " + e.getMessage());
        }
    }
}

class KurirPalsu {
    private final Deque<Boolean> jadwal = new ArrayDeque<>();

    KurirPalsu(String pola) {
        for (char c : pola.toCharArray()) {
            jadwal.add(c == 'o');
        }
    }

    String lacak(String resi) {
        if (!jadwal.isEmpty() && !jadwal.poll()) {
            throw new IllegalStateException("server kurir sibuk");
        }
        return resi + ": dalam perjalanan";
    }
}

